// Versie 1.4.2
// De archivering gebruikt uitsluitend oorspronkelijke Outlook message ID's
// uit Code-Bron herkennen. Verwerkte vacature-items bepalen alleen welke
// bronberichten mogen worden gearchiveerd.

let origineleEmails = [];
let verwerkteVacatures = [];

try {
  origineleEmails = $('Code-Bron herkennen').all();
} catch (e) {}

try {
  verwerkteVacatures = $('Code-JSON.parse').all();
} catch (e) {}

if (origineleEmails.length === 0 || verwerkteVacatures.length === 0) {
  return [];
}

const normaliseer = (waarde) => String(waarde ?? '').trim().toLowerCase();

const verwerkteIds = new Set();
const verwerkteOnderwerpen = new Set();
const verwerkteBrokerEmails = new Set();
const verwerkteBronCodes = new Set();

for (const item of verwerkteVacatures) {
  const j = item.json || {};

  const id = String(j.bronBerichtId ?? '').trim();
  const onderwerp = normaliseer(j.bronBerichtOnderwerp);
  const brokerEmail = normaliseer(j.brokerEmail);
  const broker = normaliseer(j.broker);

  if (id) verwerkteIds.add(id);
  if (onderwerp) verwerkteOnderwerpen.add(onderwerp);
  if (brokerEmail) verwerkteBrokerEmails.add(brokerEmail);

  if (broker.includes('liblab')) verwerkteBronCodes.add('liblab');
  if (broker.includes('circle8')) verwerkteBronCodes.add('circle8');
  if (broker.includes('bluetrail')) verwerkteBronCodes.add('bluetrail');
  if (broker.includes('publieke partner')) {
    verwerkteBronCodes.add('depubliekepartner');
  }
}

const uniekeEmails = new Map();

for (const item of origineleEmails) {
  const j = item.json || {};

  // DPP wordt vanaf v1.5.2 via een onafhankelijke archiveringsroute
  // afgehandeld, ook als er nul geldige vacatures zijn.
  if (normaliseer(j.bronCode) === 'depubliekepartner') {
    continue;
  }

  const origineelMessageId = String(j.id ?? '').trim();
  if (!origineelMessageId) continue;

  const onderwerp = normaliseer(j.subject ?? j.bronBerichtOnderwerp);
  const brokerEmail = normaliseer(j.brokerEmail);
  const bronCode = normaliseer(j.bronCode);

  const exactIdGevonden = verwerkteIds.has(origineelMessageId);
  const onderwerpGevonden =
    Boolean(onderwerp) && verwerkteOnderwerpen.has(onderwerp);
  const brokerEmailGevonden =
    Boolean(brokerEmail) && verwerkteBrokerEmails.has(brokerEmail);
  const bronGevonden =
    Boolean(bronCode) && verwerkteBronCodes.has(bronCode);

  const moetArchiveren =
    exactIdGevonden ||
    onderwerpGevonden ||
    (brokerEmailGevonden && bronGevonden);

  if (!moetArchiveren) continue;

  if (!uniekeEmails.has(origineelMessageId)) {
    uniekeEmails.set(origineelMessageId, {
      json: {
        bronBerichtId: origineelMessageId,
        origineelOutlookMessageId: origineelMessageId,
        internetMessageId: j.internetMessageId ?? '',
        conversationId: j.conversationId ?? '',
        bronBerichtOnderwerp: String(
          j.subject ?? j.bronBerichtOnderwerp ?? ''
        ).trim(),
        broker: j.broker ?? '',
        brokerEmail: j.brokerEmail ?? '',
        bronCode: j.bronCode ?? '',
        emailOntvangenOp:
          j.receivedDateTime ??
          j.emailOntvangenOp ??
          j.sentDateTime ??
          '',
        archiveSelectieReden:
          exactIdGevonden
            ? 'exact_message_id'
            : onderwerpGevonden
              ? 'onderwerp'
              : 'broker_en_bron'
      }
    });
  }
}

return Array.from(uniekeEmails.values());

function haalAfzenderEmailOp(message = {}) {
  const mogelijkeWaarden = [
    message.from?.emailAddress?.address,
    message.sender?.emailAddress?.address,
    message.from?.address,
    message.sender?.address,
    message.from,
    message.sender
  ];

  for (const waarde of mogelijkeWaarden) {
    if (typeof waarde === 'string' && waarde.trim()) {
      return waarde.trim().toLowerCase();
    }
  }

  return '';
}

function bepaalBron(brokerEmail = '') {
  const email = String(brokerEmail || '').trim().toLowerCase();

  if (email === 'no-reply@liblab.nl') {
    return {
      bronCode: 'liblab',
      broker: 'LibLab'
    };
  }

  if (email === 'recruitment@circle8.nl') {
    return {
      bronCode: 'circle8',
      broker: 'Circle8'
    };
  }


  if (email === 'info@bluetrail.nl' || email.endsWith('@bluetrail.nl')) {
    return {
      bronCode: 'bluetrail',
      broker: 'BlueTrail'
    };
  }

  // Versie 1.5.2:
  // accepteer ieder geldig afzenderadres binnen het DPP-domein.
  if (
    email === 'depubliekepartner.nl' ||
    email.endsWith('@depubliekepartner.nl')
  ) {
    return {
      bronCode: 'depubliekepartner',
      broker: 'de Publieke Partner'
    };
  }

  return {
    bronCode: 'onbekend',
    broker: 'Onbekend'
  };
}

return $input.all().map((item) => {
  const message = item.json;
  const brokerEmail = haalAfzenderEmailOp(message);
  const bron = bepaalBron(brokerEmail);

  return {
    json: {
      ...message,
      bronCode: bron.bronCode,
      broker: bron.broker,
      brokerEmail,
      bronBerichtId: message.id ?? '',
      bronBerichtOnderwerp: String(message.subject ?? '').trim(),
      emailOntvangenOp:
        message.receivedDateTime ??
        message.sentDateTime ??
        ''
    }
  };
});

function htmlNaarTekst(html = '') {
  return String(html)
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li[^>]*>/gi, '• ')
    .replace(/<\/tr>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&euro;/gi, '€');
}

function normaliseerTekst(tekst = '') {
  return String(tekst)
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .replace(/\u00a0/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function verwijderHandtekening(tekst = '') {
  const markers = [
    '\nMet vriendelijke groet',
    '\nKind regards',
    '\nRECRUITMENT & RESOURCING',
    '\nDisclaimer:'
  ];

  let eindPositie = tekst.length;

  for (const marker of markers) {
    const positie = tekst.toLowerCase().indexOf(marker.toLowerCase());

    if (positie !== -1 && positie < eindPositie) {
      eindPositie = positie;
    }
  }

  return tekst.slice(0, eindPositie).trim();
}

function zoekWaarde(tekst, patroon, groep = 1) {
  const resultaat = String(tekst).match(patroon);

  if (!resultaat) {
    return '';
  }

  return String(resultaat[groep] ?? '').trim();
}

function haalVacatureUrlUitHtml(html = '') {
  const vacatureLink = String(html).match(
    /<a[^>]+href=["']([^"']+)["'][^>]*>[\s\S]*?vacature op onze website[\s\S]*?<\/a>/i
  );

  if (vacatureLink?.[1]) {
    return vacatureLink[1]
      .replace(/&amp;/gi, '&')
      .trim();
  }

  return '';
}

const output = [];

for (const item of $input.all()) {
  const bericht = item.json;

  const onderwerp = String(
    bericht.bronBerichtOnderwerp ??
    bericht.subject ??
    ''
  ).trim();

  const bodyInhoud = String(
    bericht.body?.content ??
    bericht.body?.Content ??
    bericht.body ??
    bericht.bodyPreview ??
    ''
  );

  const bodyType = String(
    bericht.body?.contentType ??
    bericht.body?.ContentType ??
    ''
  ).toLowerCase();

  let volledigeTekst;

  if (bodyType === 'html' || /<[^>]+>/.test(bodyInhoud)) {
    volledigeTekst = htmlNaarTekst(bodyInhoud);
  } else {
    volledigeTekst = bodyInhoud;
  }

  volledigeTekst = normaliseerTekst(volledigeTekst);

  const vacatureTekst = verwijderHandtekening(volledigeTekst);

  const vacatureNummer =
    zoekWaarde(onderwerp, /\b(VNR-\d+)\b/i) ||
    zoekWaarde(vacatureTekst, /\b(VNR-\d+)\b/i);

  let vacatureTitel = zoekWaarde(
    onderwerp,
    /Nieuwe opdracht\s*[-–—]\s*(.+?)\s*\(VNR-\d+\)/i
  );

  if (!vacatureTitel) {
    vacatureTitel = zoekWaarde(
      vacatureTekst,
      /zijn we op zoek naar\s+(?:een\s*:?\s*)?(.+?)\s*\(VNR-\d+\)/i
    );
  }

  if (!vacatureTitel) {
    vacatureTitel = onderwerp
      .replace(/^Circle8\s*[-–—]\s*/i, '')
      .replace(/^Nieuwe opdracht\s*[-–—]\s*/i, '')
      .replace(/\s*\(VNR-\d+\)\s*/i, '')
      .trim();
  }

  const opdrachtgever = zoekWaarde(
    vacatureTekst,
    /Voor onze opdrachtgever\s+(.+?)\s+zijn we op zoek naar/i
  );

  const sluitingsdatum = zoekWaarde(
    vacatureTekst,
    /Uiterlijk aanleveren op\s+([0-9]{1,2}-[0-9]{1,2}-[0-9]{4}\s+[0-9]{1,2}:[0-9]{2})/i
  );

  const standplaats = zoekWaarde(
    vacatureTekst,
    /Standplaats\s*:\s*([^\n]+)/i
  );

  const schaal = zoekWaarde(
    vacatureTekst,
    /Schaal\s*:\s*([^\n]+)/i
  );

  const maximaalUurtarief = zoekWaarde(
    vacatureTekst,
    /Maximaal uurtarief[^€\d]*€?\s*([\d.,]+)/i
  );

  const urenPerWeek = zoekWaarde(
    vacatureTekst,
    /(\d{1,2}\s*[-–]\s*\d{1,2}\s*uur per week)/i
  );

  const vacatureUrl = haalVacatureUrlUitHtml(bodyInhoud);

  output.push({
    json: {
      vacatureTitel,
      vacatureTekst,
      vacatureUrl,

      vacatureNummer,
      opdrachtgever,
      sluitingsdatum,
      standplaats,
      schaal,
      maximaalUurtarief,
      urenPerWeek,

      broker: bericht.broker ?? 'Circle8',
      brokerEmail:
        bericht.brokerEmail ??
        'recruitment@circle8.nl',

      emailOntvangenOp:
        bericht.emailOntvangenOp ??
        bericht.receivedDateTime ??
        bericht.sentDateTime ??
        '',

      bronBerichtId:
        bericht.bronBerichtId ??
        bericht.id ??
        '',

      bronBerichtOnderwerp: onderwerp
    }
  });
}

return output;

