function responseObj(j){
  if(j&&typeof j==='object'&&!Array.isArray(j)&&(j.html_items!==undefined||j.query_data!==undefined)) return j;
  if(j&&typeof j.body==='object') return j.body;
  if(j&&typeof j.data==='object') return j.data;
  for(const x of [j?.body,j?.data,j?.response]){
    if(typeof x==='string'&&x.trim()){try{return JSON.parse(x);}catch(e){}}
  }
  if(typeof j==='string'){try{return JSON.parse(j);}catch(e){}}
  return {};
}
function parse(html=''){
  const out=[];
  const rx=/<a[^>]+href=["'](https?:\\?\/\\?\/depubliekepartner\.nl\\?\/[^"']+)["'][^>]*>\s*<h2[^>]*class=["'][^"']*\bue_job_title\b[^"']*["'][^>]*>([\s\S]*?)<\/h2>/gi;
