// v1.7.1 - robuuste BlueTrail-linkextractie uit HTML én platte Outlook-tekst.
// Belangrijkste fix: de plain-text fallback wordt altijd uitgevoerd. In sommige
// Outlook-berichten staan vacaturelinks als "Titel <https://...>", terwijl er
// elders in dezelfde e-mail wel HTML-ankers voorkomen. v1.7.0 sloeg die links over.

const output = [];
const gezien = new Set();

function decodeHtml(value = '') {
  return String(value)
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)));
}

function tekstUitHtml(value = '') {
  return decodeHtml(String(value).replace(/<[^>]+>/g, ' '))
    .replace(/\u00ad/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function normaliseerBronTekst(value = '') {
  return String(value)
    .replace(/=\r?\n/g, '') // quoted-printable soft line breaks
    .replace(/\r/g, '')
    .replace(/\u00ad/g, '');
}

function normaliseerUrl(value = '') {
  return decodeHtml(String(value))
    .replace(/=\r?\n/g, '')
    .replace(/=3D/gi, '=')
    .replace(/\s+/g, '')
    .replace(/[),.;]+$/g, '')
    .trim();
}

function isBlueTrailUrl(url = '') {
  return /^https?:\/\/(?:return\.)?bluetrail\.nl\//i.test(url) ||
    /^https?:\/\/(?:www\.)?bluetrail\.nl\//i.test(url);
}

function isVacatureTitel(label = '') {
  const l = String(label).replace(/\s+/g, ' ').trim();
  if (!l || l.length < 3 || l.length > 180) return false;
  if (/^(bekijk deze opdracht|lees meer|klik hier|website|home|vacature bekijken)$/i.test(l)) return false;
  if (/uitschrijven|unsubscribe|privacy|linkedin|facebook|instagram|contact/i.test(l)) return false;
  if (/job alert header|logo|vacature alert|speciaal voor jou geselecteerd/i.test(l)) return false;
  return true;
}

function voegToe(metadata, url, titel, inputIndex) {
  const vacatureUrl = normaliseerUrl(url);
  const vacatureTitelEmail = tekstUitHtml(titel);
  if (!isBlueTrailUrl(vacatureUrl) || !isVacatureTitel(vacatureTitelEmail)) return;

  // Eén titel-link per vacature. CTA-links worden door titelcontrole uitgesloten.
  const sleutel = `${vacatureUrl.toLowerCase()}|${vacatureTitelEmail.toLowerCase()}`;
  if (gezien.has(sleutel)) return;
  gezien.add(sleutel);

  output.push({
    json: {
      ...metadata,
      vacatureUrl,
      vacatureTitelEmail,
      vacatureTitel: vacatureTitelEmail
    },
    pairedItem: { item: inputIndex }
  });
}

const items = $input.all();
for (let inputIndex = 0; inputIndex < items.length; inputIndex++) {
  const j = items[inputIndex].json || {};
  const body = j.body?.content ?? j.body ?? j.text ?? j.content ?? '';
  const raw = typeof body === 'string' ? body : JSON.stringify(body);
  const inhoud = normaliseerBronTekst(raw);

  const metadata = {
    broker: j.broker || 'BlueTrail',
    brokerEmail: j.brokerEmail || j.from?.emailAddress?.address || 'info@bluetrail.nl',
    bronCode: 'bluetrail',
    bronBerichtId: j.bronBerichtId || j.id || '',
    bronBerichtOnderwerp: j.bronBerichtOnderwerp || j.subject || '',
    emailOntvangenOp: j.emailOntvangenOp || j.receivedDateTime || j.createdDateTime || ''
  };

  // 1. Normale HTML-ankers.
  const anchorRegex = /<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
  let match;
  while ((match = anchorRegex.exec(inhoud)) !== null) {
    voegToe(metadata, match[1], match[2], inputIndex);
  }

  // 2. Outlook/plain-text patroon: Functietitel <https://return.bluetrail.nl/...>
  // Altijd uitvoeren; niet alleen wanneer de mail helemaal geen <a>-tags bevat.
  const plainRegex = /(?:^|\n)\s*([^\n<>]{3,180}?)\s*<((?:https?:\/\/)(?:(?:return\.)?bluetrail\.nl|(?:www\.)?bluetrail\.nl)\/[^>\s]+)>/gi;
  while ((match = plainRegex.exec(inhoud)) !== null) {
    voegToe(metadata, match[2], match[1], inputIndex);
  }

  // 3. Extra fallback voor Outlook dat URL en titel op opeenvolgende regels zet.
  const regels = inhoud.split('\n');
  for (let r = 0; r < regels.length; r++) {
    const regel = regels[r].trim();
    const urlMatch = regel.match(/<?(https?:\/\/(?:(?:return\.)?bluetrail\.nl|(?:www\.)?bluetrail\.nl)\/[^>\s]+)>?/i);
    if (!urlMatch) continue;
    const kandidaatTitel = (regels[r - 1] || '').trim();
    voegToe(metadata, urlMatch[1], kandidaatTitel, inputIndex);
  }
}

const state = $getWorkflowStaticData('global');
state.laatsteBlueTrailLinkExtractie = {
