return output.slice(0, limiet);

// v1.7.0 - normaliseert een BlueTrail vacaturepagina naar het centrale formaat.
const httpItems = $input.all();
const bronItems = $('Code-BlueTrail vacature-URLs').all();

function decodeHtml(value = '') {
  return String(value)
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
    .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCodePoint(parseInt(n, 16)))
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&apos;|&#39;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>');
}

function htmlNaarTekst(html = '') {
  return decodeHtml(String(html)
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<svg\b[^>]*>[\s\S]*?<\/svg>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<(br|hr)\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|section|article|li|h1|h2|h3|h4|h5|h6|tr|ul|ol)>/gi, '\n')
    .replace(/<li\b[^>]*>/gi, '• ')
    .replace(/<[^>]+>/g, ' '))
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function meta(html, name) {
  const safe = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const patterns = [
    new RegExp(`<meta[^>]+(?:name|property)=["']${safe}["'][^>]+content=["']([^"']*)["']`, 'i'),
    new RegExp(`<meta[^>]+content=["']([^"']*)["'][^>]+(?:name|property)=["']${safe}["']`, 'i')
  ];
  for (const p of patterns) {
    const m = String(html).match(p);
    if (m?.[1]) return decodeHtml(m[1]).trim();
  }
  return '';
}

function titel(html, fallback = '') {
  const kandidaten = [
    meta(html, 'og:title'),
    meta(html, 'twitter:title'),
    String(html).match(/<h1\b[^>]*>([\s\S]*?)<\/h1>/i)?.[1],
    fallback,
    String(html).match(/<title\b[^>]*>([\s\S]*?)<\/title>/i)?.[1]
  ];
  for (const k of kandidaten) {
    const t = htmlNaarTekst(k || '')
      .replace(/\s*[|–-]\s*BlueTrail.*$/i, '')
      .replace(/^Vacature\s*[:|-]?\s*/i, '')
      .trim();
    if (t) return t;
  }
  return '';
}

function vacatureTekst(html) {
  const patterns = [
    /<article\b[^>]*>([\s\S]*?)<\/article>/i,
    /<main\b[^>]*>([\s\S]*?)<\/main>/i,
    /<div\b[^>]+class=["'][^"']*(?:vacature|job|opdracht|content)[^"']*["'][^>]*>([\s\S]*?)<\/div>/i
  ];
  for (const p of patterns) {
    const m = String(html).match(p);
    if (m?.[1]) {
      const t = htmlNaarTekst(m[1]);
      if (t.length >= 100) return t;
    }
  }
  return htmlNaarTekst(html);
}

function opdrachtgever(text = '') {
  const patterns = [
    /(?:opdrachtgever|klant|organisatie)\s*[:\-]\s*([^\n|]{2,100})/i,
    /(?:voor onze klant|voor)\s+([A-ZÀ-Ý][^\n,.]{2,80})/i
  ];
  for (const p of patterns) {
    const m = String(text).match(p);
    if (m?.[1]) return m[1].replace(/\s+/g,' ').replace(/[.;,:]+$/,'').trim();
  }
  return '';
}

return httpItems.map((item, index) => {
  const h = item.json || {};
  const b = bronItems[index]?.json || {};
  const html = typeof h.data === 'string' ? h.data
    : typeof h.body === 'string' ? h.body
    : typeof h.content === 'string' ? h.content
    : typeof h === 'string' ? h : '';

  const tekst = vacatureTekst(html);
  const status = html && tekst.length >= 100 ? 'verwerkt' : 'ongeldig';

  return {
    json: {
      vacatureTitel: titel(html, b.vacatureTitelEmail || b.vacatureTitel),
      vacatureTekst: tekst,
      vacatureUrl: b.vacatureUrl || h.url || '',
      broker: 'BlueTrail',
      brokerEmail: b.brokerEmail || 'info@bluetrail.nl',
      bronCode: 'bluetrail',
      opdrachtgever: opdrachtgever(tekst),
      emailOntvangenOp: b.emailOntvangenOp || '',
      bronBerichtId: b.bronBerichtId || '',
      bronBerichtOnderwerp: b.bronBerichtOnderwerp || '',
      vacatureTitelEmail: b.vacatureTitelEmail || '',
      blueTrailDetailStatus: status,
      blueTrailDetailFout: status === 'verwerkt' ? '' : 'Geen bruikbare vacaturepagina ontvangen',
      bronHtml: html
    },
    pairedItem: { item: index }
  };
});

// v1.7.0 - laat alleen bruikbare BlueTrail-vacatures door.
const geldig = [];
const overgeslagen = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const titel = String(j.vacatureTitel || '').trim();
  const tekst = String(j.vacatureTekst || '').trim();
  if (j.blueTrailDetailStatus === 'verwerkt' && titel && tekst.length >= 100) {
    geldig.push(item);
  } else {
    overgeslagen.push({url:j.vacatureUrl || '',titel,fout:j.blueTrailDetailFout || 'Onvolledige BlueTrail-vacature'});
  }
}
const state = $getWorkflowStaticData('global');
state.laatsteBlueTrailResultaat = {
  gemetenOp:new Date().toISOString(),
  ontvangen:$input.all().length,
  geldig:geldig.length,
  overgeslagen:overgeslagen.length,
  fouten:overgeslagen.slice(0,25)
};
return geldig;
